import React from "react";

export function AvatarStack({ initials = ["SC", "AD", "KM", "EL"] }: { initials?: string[] }) {
  return (
    <div className="flex -space-x-2">
      {initials.map((init, i) => (
        <div key={i} className="w-9 h-9 rounded-full border-2 border-card bg-muted text-foreground flex items-center justify-center font-mono text-xs font-semibold">{init}</div>
      ))}
    </div>
  );
}
